const Context=React.createContext(null);
function initial(){if(typeof window==='undefined')return'es';const saved=localStorage.getItem(KEY);if(SUPPORTED_LOCALES.includes(saved))return saved;const browser=(navigator.language||'es').toLowerCase();const candidate=browser.startsWith('nb')||browser.startsWith('nn')?'no':browser.slice(0,2);return SUPPORTED_LOCALES.includes(candidate)?candidate:'es'}
export function I18nProvider({children}){const[locale,setState]=React.useState(initial);const setLocale=React.useCallback(next=>{if(!SUPPORTED_LOCALES.includes(next))return;setState(next);try{localStorage.setItem(KEY,next)}catch{}},[]);React.useEffect(()=>{document.documentElement.lang=locale},[locale]);const t=React.useCallback((key,fallback)=>{const get=(obj,path)=>path.split('.').reduce((v,k)=>v?.[k],obj);return get(messages[locale],key)??get(messages.es,key)??fallback??key},[locale]);return <Context.Provider value={{locale,setLocale,t}}>{children}</Context.Provider>}
export function useI18n(){const value=React.useContext(Context);return value||{locale:'es',setLocale:()=>{},t:(k,f)=>messages.es[k]??f??k}}
